   ⋮            segments: [
   ⋮                PathSegment {
   ⋮                    ident: "fut",
   ⋮                    arguments: None,
   ⋮                },
   ⋮            ],
   ⋮        },
   ⋮    },
   ⋮}
    "###);
}

```

