use nalgebra::{Isometry3, Matrix4, Perspective3, Point3, Real, Scalar, Vector3};

pub struct Camera<T>
where
    T: Real + Scalar,
{
    projection: Perspective3<T>,
    view: Isometry3<T>,
}

impl<T> Camera<T>
where
    T: Real + Scalar,
{
    pub fn new(aspect: T, fov: T, near: T, far: T) -> Self {
        Camera {
            projection: Perspective3::new(aspect, fov, near, far),
