    let r = Rc::new(RefCell::new(42));
    *r.borrow_mut() += 10;
    let x = *r.borrow();
    x
}

fn arc() -> Arc<i32> {
    let a = Arc::new(42);
    a
}

fn true_assert() {
    assert_eq!(1, 1);
}

fn main() {
    assert_eq!(*arc(), 42);
    assert_eq!(rc_cell().get(), 84);
    assert_eq!(rc_refcell(), 52);
    true_assert();
}

```

