                                 .unwrap_or_else(|e| e.exit());

    let mut world = world::World::new(args.flag_width, args.flag_height);

    world.randomize();

    loop {
        world = world.evolve();
        println!("\x1b[2J\n{}", world);
        std::thread::sleep_ms(args.flag_period);
    }
}

