          mem};

use libc;

use crate::{error::{Error,
                    Result},
            os::system::Uname};
use errno::errno;

pub fn uname() -> Result<Uname> { unsafe { uname_libc() } }

unsafe fn uname_libc() -> Result<Uname> {
    let mut utsname: libc::utsname = mem::uninitialized();
    let rv = libc::uname(&mut utsname);
