extern crate toml;
use config::Config;
use std::env;
use std::fs::File;
use std::io::Read;

pub struct Workflow {
    config: Config,
}

pub fn new() -> Workflow {
    let config = load_config().unwrap();
    Workflow {
        config: config,
    }
}

fn load_config() -> Result<Config, String> {
    let mut config_file = env::home_dir().unwrap();
    config_file.push(".jiraconfig");
