worked_solution:
Root Cause Resolution & Patch:
Increase default expiry time for integration tests

During reindexing, the transaction may expire, this causes the tx
manager to (correctly) purge the tx from the database. By increasing the
default expiry, we can ensure that the tx will remain in the db for as
long as necessary.

Repaired production-quality implementation:
```rust
use godcoin::{constants::MAX_TX_SIGNATURES, prelude::*};

pub mod minter;
pub use minter::*;

pub fn get_asset(grael: &str) -> Asset {
    grael.parse().unwrap()
}

pub fn create_tx_header(fee: &str) -> Tx {
    let expiry = godcoin::get_epoch_time() + 30;
    create_tx_header_with_expiry(fee, expiry)
}

pub fn create_tx_header_with_expiry(fee: &str, expiry: u64) -> Tx {
    let nonce: u32 = {
        let mut nonce = [0; 4];
        sodiumoxide::randombytes::randombytes_into(&mut nonce);
        u32::from_ne_bytes(nonce)
    };
    Tx {
        nonce,
        expiry,
        fee: fee.parse().unwrap(),
        signature_pairs: Vec::with_capacity(MAX_TX_SIGNATURES),
    }
}

pub fn check_sigs(tx: &TxVariant) -> bool {
    let mut buf = Vec::with_capacity(4096);
    tx.serialize_without_sigs(&mut buf);
    for sig_pair in tx.sigs() {
        if !sig_pair.verify(&buf) {
            return false;
        }
    }

    true
}

```

