use {Parcel, Error, Settings};
use hint;
use std::io::prelude::*;

use uuid::Uuid;

impl Parcel for Uuid
{
    const TYPE_NAME: &'static str = "Uuid";

    fn read(read: &mut Read,
            _: &Settings,
            _: &mut hint::Hints)
        -> Result<Self, Error> {
        let bytes: Result<Vec<u8>, _> = read.bytes().take(16).collect();
        let bytes = bytes?;

