use package::Package;

/// The struct which represents the repos.
#[derive(Deserialize)]
pub struct Repository {
    url: String,
    packages: Vec<Package>,
}

/// Struct which represents a list of Repositories.
#[derive(Deserialize)]
struct RepositoryList(Vec<Repository>);

