impl<'a, 'b, E> ops::Shl<&'a [u8]> for &'b mut Write<Error=E> {
    type Output = Self;

    /// Fakes the C++ `<<` operator for IOStreams on Write.
    fn shl(self, _rhs: &'a [u8]) -> Self::Output {
        try!(self.write(_rhs));
        self
    }
}

