        .for_each(|n| println!("{}\t=>\t{}", n, n.pow(2)))
}

fn is_automorphic(n: i128) -> bool {
    let n_str = n.to_string();
    let sq_str = n.pow(2).to_string();
    n_str == sq_str[(sq_str.len() - n_str.len())..]
}

fn main() {
    list_automorphic_numbers(1, 10000)
}

